import pytest


def key_match_paged(key0: list[int], key1: list[int], page_size: int) -> int:
    """Return the common prefix length, rounded down to whole pages.

    Matching stops at the first differing token. A trailing page that is
    incomplete or only partially matches is not counted.
    """
    if page_size < 1:
        raise ValueError("page_size must be >= 1")

    matched_tokens = 0
    for token0, token1 in zip(key0, key1):
        if token0 != token1:
            break
        matched_tokens += 1

    return (matched_tokens // page_size) * page_size


def test_page_size_one_returns_exact_matching_prefix():
    assert key_match_paged([1, 2, 3], [1, 2, 4], 1) == 2


